const HOST = env.get('HOST');
const PORT = Number(env.get('PORT'));
const ADDRESS = Number(env.get('ADDRESS'));
const PASSWORD = env.get('PASSWORD') || '111111';

const { Mercury230Client } = global.get('mercury230');
const { withConnectionLock } = global.get('withConnectionLock');

(async () => {
    try {
        const deviceState = await withConnectionLock(HOST, PORT, async () => {
            const client = new Mercury230Client({ host: HOST, port: PORT, address: ADDRESS, password: PASSWORD });
            // Mercury230Client.read() opens the socket and the channel, reads
            // the identity, clock, instant values and energy registers, then
            // closes the channel and the socket itself.
            return await client.read();
        });

        node.send({ payload: deviceState });
        node.status({ fill: 'green', shape: 'dot', text: 'ok ' + new Date().toLocaleTimeString() });
    } catch (err) {
        // Full read failed — nothing goes out. No partial/incomplete set is sent downstream.
        node.error('Mercury230 read failed: ' + err.message);
        node.status({ fill: 'red', shape: 'ring', text: 'error' });
    }
})();

return null;

const HOST = env.get('HOST');
const PORT = Number(env.get('PORT'));
const EVEN_PARITY_RAW = env.get('EVEN_PARITY');
const EVEN_PARITY = EVEN_PARITY_RAW === true || EVEN_PARITY_RAW === 'true';
const STEP_DELAY_MS = Number(env.get('STEP_DELAY_MS')) || 300;
const RESPONSE_TIMEOUT_MS = Number(env.get('RESPONSE_TIMEOUT_MS')) || 30000;

const { Ek270Iec61107Client } = global.get('ek270Iec61107');
const { withConnectionLock } = global.get('withConnectionLock');

(async () => {
    try {
        const deviceState = await withConnectionLock(HOST, PORT, async () => {
            const client = new Ek270Iec61107Client({
                host: HOST,
                port: PORT,
                evenParity: EVEN_PARITY,
                stepDelayMs: STEP_DELAY_MS,
                responseTimeoutMs: RESPONSE_TIMEOUT_MS,
            });
            // Ek270Iec61107Client.read() opens the socket, runs the full
            // IEC 61107 handshake, reads every parameter and closes the
            // socket itself — unlike Mercury230Client there is no separate
            // connect()/disconnect() step to call here.
            return await client.read();
        });

        msg.payload = deviceState;
        node.send(msg);
        node.status({ fill: 'green', shape: 'dot', text: 'ok ' + new Date().toLocaleTimeString() });
    } catch (err) {
        // Full read failed — nothing goes out. No partial/incomplete set is sent downstream.
        node.error('EK270 read failed: ' + err.message, msg);
        node.status({ fill: 'red', shape: 'ring', text: 'error' });
    }
})();

return null;

const HOST = env.get('HOST');
const PORT = Number(env.get('PORT'));
const ADDRESS = Number(env.get('ADDRESS'));
const WAKE_UP_BYTES = Number(env.get('WAKE_UP_BYTES'));
const RESPONSE_TIMEOUT_MS = Number(env.get('RESPONSE_TIMEOUT_MS')) || 60000;
const BARS02_ID = env.get('BARS02_ID');
const BARS02_LISTEN_PORT = Number(env.get('BARS02_LISTEN_PORT')) || 2910;
const BARS02_LINE = env.get('BARS02_LINE') || 'rs232-powered 9600 8N1';

const { Vkt7Client } = global.get('vkt7');
const { withConnectionLock } = global.get('withConnectionLock');
const bars02 = global.get('bars02');

// Through a БАРС-02 GPRS unit: it connects to the gateway listening on
// BARS02_LISTEN_PORT, which serves one meter per unit at a time. Over GPRS a
// request takes 4-5 s and a whole read 30-90 s.
async function readThroughBars02() {
    const gateway = bars02.getGateway(BARS02_LISTEN_PORT);
    await gateway.ready;
    const line = bars02.parseLineSettings(BARS02_LINE);
    const client = new Vkt7Client({
        address: ADDRESS,
        wakeUpBytes: Number.isNaN(WAKE_UP_BYTES) ? 2 : WAKE_UP_BYTES,
        stepTimeoutMs: 15000,
        responseTimeoutMs: Math.max(RESPONSE_TIMEOUT_MS, 240000),
        createSocket: () => gateway.createSocket({ identifier: BARS02_ID, ...line }),
    });
    return await client.read();
}

(async () => {
    try {
        const deviceState = BARS02_ID ? await readThroughBars02() : await withConnectionLock(HOST, PORT, async () => {
            const client = new Vkt7Client({
                host: HOST,
                port: PORT,
                address: ADDRESS,
                wakeUpBytes: Number.isNaN(WAKE_UP_BYTES) ? 2 : WAKE_UP_BYTES,
                responseTimeoutMs: RESPONSE_TIMEOUT_MS,
            });
            // Vkt7Client.read() opens the socket, runs the whole session
            // (service info, properties, current values, current totals,
            // clock) and closes the socket itself.
            return await client.read();
        });

        msg.payload = deviceState;
        node.send(msg);
        node.status({ fill: 'green', shape: 'dot', text: 'ok ' + new Date().toLocaleTimeString() });
    } catch (err) {
        // Full read failed — nothing goes out. No partial/incomplete set is sent downstream.
        node.error('VKT-7 read failed: ' + err.message, msg);
        node.status({ fill: 'red', shape: 'ring', text: 'error' });
    }
})();

return null;

