// Flag words (protocol table 1.4.1): Fl_b keeps three states in each of its
// low bit pairs, single flags in the bits above; Fl_a keeps single flags.
const pair = (shift) => (meter >> shift) & 0b11;
const bit = (word, shift) => ((word >> shift) & 1) === 1;

