    // Measured values
    volumeStandard: payload.Vnc,                     // accumulated volume at standard conditions, m³
    volumeFlowRateStandard: payload.Qnc,             // flow rate at standard conditions, nm³/h
    volumeFlowRateWorking: payload.Qwc,              // flow rate at working conditions, m³/h
    pressure: payload.P,                             // gas pressure, kPa
    temperature: payload.T === null ? null : Number((payload.T - 273.15).toFixed(4)), // gas temperature, °C (the meter sends K)
    operatingTime: payload.operatingTimeHours + payload.operatingTimeMinutes / 60 + payload.operatingTimeSeconds / 3600, // operating time (наработка), h

    // Raw flag words
    generalFlags: general,                           // general flag word Fl_a
    meterFlags: meter,                               // flow-meter flag word Fl_b

    // Flags from Fl_a
    powerOffFlag: bit(general, 0),                   // power was off
    dateTimeChangedFlag: bit(general, 1),            // date/time was changed
    clockFailureFlag: bit(general, 2),               // clock failure

    // Flags from Fl_b
    lowFlowRateFlag: pair(0) === 1,                  // flow below the measuring range
    highFlowRateFlag: pair(0) === 2,                 // flow above the measuring range
    highSensorFrequencyFlag: pair(0) === 3,          // sensor signal frequency (FQ) above the range
    waterInFlowSensorFlag: pair(2) === 1,            // water in the flow sensor
    flowSensorFailureFlag: pair(2) === 2,            // flow sensor failure
    noFlowFlag: pair(2) === 3,                       // no flow
    badFlowSignalFlag: pair(4) === 1,                // bad flow-sensor signal
    flowSignalAnalysisFlag: pair(4) === 2,           // flow signal being analysed
    temperatureOutOfRangeFlag: bit(meter, 6),        // temperature out of range
    pressureOutOfRangeFlag: bit(meter, 7),           // pressure out of range
    noDataFlag: bit(meter, 8),                       // no data from the flow meter
    constantsArchiveRecordFlag: bit(meter, 9),       // contract values or gas composition changed (constants-archive record)
    badSignalAccountingFlag: bit(meter, 10),         // "account gas at a bad signal" was on at the archive record

    // Timestamp
    timestamp: Date.now(),
};

