const dPtoa = (Pe12 - Pe23) * 10;  // сопротивление теплообменного аппарата
const dPcphw = (Pe3 - Pe22) * 10;  // располагаемый напор насоса за вычетом сопротивления фильтра
const dPhws = (Pe12 - Pe22) * 10;  // сопротивление системы ГВС
const lim_dPtoa = 2;               // граница по максимальному сопротивлению теплообменника
const limH_dPcphw = 8;             // граница по максимальному напору насоса
const limL_dPcphw = 3;             // граница по минимальному напору насоса
const limH_dPhws = 5;              // граница по максимальному сопротивлению системы ГВС
const limH_Te12 = 68;              // граница по максимальной температуре в систему ГВС
const limL_Te12 = 62;              // граница по минимальной температуре в систему ГВС
const limL_Te22 = 55;              // граница по минимальной температуре из системы ГВС
const limH_Te2  = 35;              // граница по максимальной температуре возвращаемого теплоносителя в сеть

const deviceState = {
    tempOutAir: Tair,               // Тн.в.
    tempInHWS: Te12,                // TE12 - Температура на подаче контура ГВ (°C)
    tempOutHWS: Te22,                // TE22 - Температура обратки ГВ (°C) 
    tempOutNet: Te2,                // TE2 - Температура обратки в сеть (°C) 
    pressInHWS:         Pe12,       // PE12 - Давление на подаче горячей воды (бар)
    pressOutNet:        Pe22,      // PE22 - Давление на обратке горячей воды (бар)
    pressOutAfterPump:  Pe3,       // PE3 - Давление на обратке после насоса (бар)
    pressInCW:          Pe23,      // PE23 - Давление подводящей холодной воды (бар)   
    deltaPressTOA: dPtoa,
    deltaPressPump: dPcphw,
    deltaPressHWS: dPhws,
    limDeltaPressTOA: lim_dPtoa,   
    limHighDeltaPressPump: limH_dPcphw,
    limLowDeltaPressPump: limL_dPcphw,
    limHighDeltaPressHWS: limH_dPhws,
    limHighTempInHWS: limH_Te12,
    limLowTempInHWS: limL_Te12,
    limLowTempOutHWS: limL_Te22,
    limHighTempOutNet: limH_Te2,
    // Timestamp
    timestamp: Date.now(),
}

const DEVICE_CODE = 'amirkhana99-hws-node';
const flowUid = node.path.split('/').find(_ => true);
await storeDeviceStateToCacheAsync(global, DEVICE_CODE, deviceState, flowUid);

msg.payload = deviceState;

return msg;
